# Borgs that never enter the item pool: the three unobtainable in vanilla
# and the two halves of the Cyber Death Dragon: enemies, never prizes.
GALACTIC_EMPEROR = 0x0e04
CYBER_DEATH_DRAGON = 0x0503  # the whole dragon: an enemy, never a prize
DEATH_HEAD = 0x0505          # head of the Cyber Death Dragon
CYBER_DRAGON = 0x0506        # body of the Cyber Death Dragon

NEVER_IN_POOL: frozenset[int] = frozenset(
    {GALACTIC_EMPEROR, DEATH_HEAD, CYBER_DRAGON}
    | {i for i, d in BORGS.items()
       if d.name in ("Machine Head", "Mechanical Dragon")}
)

# The story borg and its upgrade can be fought but never owned as items:
# the Progressive G Red chain delivers them.
ENEMY_ONLY: dict[int, Borg] = {
    G_RED: Borg(G_RED_NAME, G_RED_COST, 1),
    NEO_G_RED: Borg(NEO_G_RED_NAME, NEO_G_RED_COST, 1),
}

# Cost and name of every id a randomization may write
COSTS: dict[int, int] = {i: b.cost for i, b in (BORGS | ENEMY_ONLY).items()}
NAMES: dict[int, str] = {i: b.name for i, b in (BORGS | ENEMY_ONLY).items()}

# Borgs a randomization may pick. Outside its own arena the Emperor hangs
# out of reach and cannot be damaged, so its mission could never be won.
RANDOMIZABLE: tuple[int, ...] = tuple(sorted((set(BORGS) | set(ENEMY_ONLY)) - {GALACTIC_EMPEROR}))
